export function validateContact(r,t){const e=[],n=String(r.name||"").trim(),i=String(r.email||"").trim(),s=String(r.message||"").trim();return(n.length<2||n.length>80)&&e.push("name"),(i.length>254||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(i))&&e.push("email"),t.includes(r.topic)||e.push("topic"),(s.length<20||s.length>4e3)&&e.push("message"),r.consent!=="on"&&e.push("consent"),e}export function submissionState(r,t){return t?.errors?.some?.(e=>e.code==="INACTIVE")?"activation":r&&t?.ok===!0&&!t.errors?.length?"received":"failed"}export function providerFieldErrors(r){const t=["name","email","topic","message","consent"];return Array.isArray(r?.errors)?[...new Set(r.errors.map(e=>e.field).filter(e=>t.includes(e)))]:[]}
